// The job id is interpolated into a shell path below. The webhook is reachable from
// the host (port 5678 is published), so accept a positive integer and nothing else.
const b = $input.first().json.body || {};
const id = Number(b.jobId !== undefined ? b.jobId : b.job_id);
if (!Number.isInteger(id) || id <= 0) {
  throw new Error('jobId must be a positive integer, got ' + JSON.stringify(b.jobId !== undefined ? b.jobId : b.job_id));
}
return [{ json: { jobId: id } }];
